x_938076_backup_0_backup_scripts.script:
var us = '224cc27e93b0c610b31a30dcebba1087';
var grpMem = []; //fetching the groups the logged in user is part of
var grpTyp = []; // fetching owning business group the logged in user is part of 
var arrayUtil = new ArrayUtil();
var myGroups = new GlideRecord('sys_user_grmember');
myGroups.addQuery('user', us);
myGroups.query();
while (myGroups.next()) {
    grpMem.push(myGroups.group.sys_id); //groups wwhich logged in user has access
    grpTyp.push(myGroups.group.type); //owning business group of the groups
}
gs.info("Users belong to groups: " + grpMem.toString()); //excluding owning business group
gs.info("Group membership Count: " + grpMem.length); //memebership counbt excluding owning business group

var type = grpTyp.toString().split(",");
var uniqType = arrayUtil.unique(type); //unique cumulative bands of the groups
gs.info("Users belong to bands: " + uniqType);

var grpList = grpMem.toString(); //sys if of groups
var gr = new GlideRecord('sys_user_group'); // change to logged in user manager
var access = [];
gr.addEncodedQuery('sys_idIN' + grpList + '^ORtypeIN' + uniqType); // return records for the logged in user memeberships and he is part of the type
gr.query();
while (gr.next()) {
    gs.info(gr.name);
	access.push(gr.sys_id);
}


gs.info("Total groups including group membership & owning business: " + access.length);

// filtering records to display based on the type and the group memebership
